import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App.jsx';

createRoot(document.getElementById('root')).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

const BASE_URL = 'http://localhost:8000/books';

export async function listBooks() {
  const res = await fetch(BASE_URL);
  if (!res.ok) throw new Error(`Failed to fetch books: ${res.status}`);
  return res.json();
}

export async function createBook(book) {
  const res = await fetch(BASE_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(book),
  });
  if (!res.ok) throw new Error(`Failed to create book: ${res.status}`);
  return res.json();
}

export async function updateBookStatus(id, status) {
  const res = await fetch(`${BASE_URL}/${id}/status`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status }),
  });
  if (!res.ok) throw new Error(`Failed to update book status: ${res.status}`);
  return res.json();
}

import { useState, useEffect } from 'react';
import { listBooks } from '../api';

export default function BookList() {
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    listBooks()
      .then(setBooks)
      .catch(setError)
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <p>Caricamento libri...</p>;
  if (error) return <p>Errore: {error.message}</p>;

  return (
    <ul>
      {books.length === 0 && <li>Nessun libro presente.</li>}
      {books.map((book) => (
        <li key={book.id}>
          <strong>{book.title}</strong> — {book.author} ({book.status})
        </li>
      ))}
    </ul>
  );
}

import { useState } from 'react';
import { createBook } from '../api';

export default function BookForm() {
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [status, setStatus] = useState('da leggere');

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await createBook({ title, author, status });
      setTitle('');
      setAuthor('');
      setStatus('da leggere');
    } catch (err) {
      console.error('Errore creazione libro:', err);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <input
        type="text"
        placeholder="Titolo"
        value={title}
        onChange={(e) => setTitle(e.target.value)}
        required
      />
      <input
        type="text"
        placeholder="Autore"
        value={author}
        onChange={(e) => setAuthor(e.target.value)}
        required
      />
      <select value={status} onChange={(e) => setStatus(e.target.value)}>
        <option value="da leggere">Da leggere</option>
        <option value="in lettura">In lettura</option>
        <option value="letto">Letto</option>
      </select>
      <button type="submit">Aggiungi libro</button>
    </form>
  );
}

